const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('node:assert');

// ---------------------------------------------------------------------------
// Shared helpers
// ---------------------------------------------------------------------------

function getDoc() {
  return this.document;
}

function qs(sel) {
  const el = getDoc.call(this).querySelector(sel);
  if (!el) throw new Error(`querySelector("${sel}") returned null`);
  return el;
}

function qsa(sel) {
  return getDoc.call(this).querySelectorAll(sel);
}

function textOf(el) {
  return (el.textContent || '').trim();
}

function findTodoLi(labelText) {
  const items = qsa.call(this, '.todo-list li');
  for (const li of items) {
    const label = li.querySelector('label');
    if (label && textOf(label) === labelText) return li;
  }
  return null;
}

function findTodoLabel(labelText) {
  const li = findTodoLi.call(this, labelText);
  return li ? li.querySelector('label') : null;
}

function isVisible(el) {
  if (!el) return false;
  if (el.style && el.style.display === 'none') return false;
  if (el.hidden) return false;
  // Check if the element or ancestor has display none via style
  let cur = el;
  while (cur) {
    if (cur.style && cur.style.display === 'none') return false;
    if (cur.hidden) return false;
    cur = cur.parentElement;
  }
  return true;
}

function isHidden(el) {
  return !isVisible.call(this, el);
}

function todoData() {
  const raw = this.window.localStorage.getItem('todos-vanilla');
  return raw ? JSON.parse(raw) : [];
}

function saveTodoData(todos) {
  this.window.localStorage.setItem('todos-vanilla', JSON.stringify(todos));
}

// ---------------------------------------------------------------------------
// Given steps
// ---------------------------------------------------------------------------

Given('the app is loaded', function () {
  assert.ok(this.document, 'app should be loaded');
  const main = this.document.querySelector('.todoapp');
  assert.ok(main, 'todoapp section should exist');
});

Given('the todo input is focused', function () {
  const input = qs.call(this, '.new-todo');
  input.focus();
  assert.strictEqual(this.document.activeElement, input, 'todo input should be focused');
});

Given('the todo list is empty', function () {
  const listEl = qs.call(this, '.todo-list');
  listEl.innerHTML = '';
  this.window.localStorage.removeItem('todos-vanilla');
  if (this.window.__render) this.window.__render();
  assert.strictEqual(qsa.call(this, '.todo-list li').length, 0, 'todo list should be empty');
});

Given('the todo list contains {string}', function (title) {
  const list = qs.call(this, '.todo-list');
  const li = this.document.createElement('li');
  li.innerHTML =
    `<div class="view"><input class="toggle" type="checkbox"><label>${title}</label><button class="destroy"></button></div><input class="edit" value="${title}">`;
  list.appendChild(li);
  const todos = todoData.call(this);
  todos.push({ id: Date.now() + Math.random(), title, completed: false });
  saveTodoData.call(this, todos);
  if (this.window.__render) this.window.__render();
  else {
    qs.call(this, '.main').style.display = 'block';
    qs.call(this, '.footer').style.display = 'block';
  }
});

Given('{string} is completed', function (title) {
  const li = findTodoLi.call(this, title);
  assert.ok(li, `todo "${title}" should exist`);
  li.classList.add('completed');
  const cb = li.querySelector('.toggle');
  if (cb) cb.checked = true;
  const todos = todoData.call(this);
  for (const t of todos) {
    if (t.title === title) { t.completed = true; break; }
  }
  saveTodoData.call(this, todos);
  if (this.window.__render) this.window.__render();
});

Given('all todos are completed', function () {
  const items = qsa.call(this, '.todo-list li');
  for (const li of items) {
    li.classList.add('completed');
    const cb = li.querySelector('.toggle');
    if (cb) cb.checked = true;
  }
  const todos = todoData.call(this);
  for (const t of todos) t.completed = true;
  saveTodoData.call(this, todos);
  if (this.window.__render) this.window.__render();
});

Given('no todos are completed', function () {
  const items = qsa.call(this, '.todo-list li');
  for (const li of items) {
    li.classList.remove('completed');
    const cb = li.querySelector('.toggle');
    if (cb) cb.checked = false;
  }
  const todos = todoData.call(this);
  for (const t of todos) t.completed = false;
  saveTodoData.call(this, todos);
  if (this.window.__render) this.window.__render();
});

Given('the route is {string}', function (route) {
  this.window.location.hash = route;
  this.window.dispatchEvent(new this.window.Event('hashchange'));
});

Given('I navigate to {string}', function (route) {
  this.navigate(route);
});

Given('localStorage contains a todo with title {string} and completed {word}', function (title, completedStr) {
  const completed = completedStr === 'true';
  const todos = todoData.call(this);
  todos.push({ id: Date.now() + Math.random(), title, completed });
  saveTodoData.call(this, todos);
  if (this.window.__render) this.window.__render();
});

// ---------------------------------------------------------------------------
// When steps
// ---------------------------------------------------------------------------

When('I type {string} into the todo input and press Enter', function (value) {
  const input = qs.call(this, '.new-todo');
  input.value = value;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
  input.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keypress', { key: 'Enter', keyCode: 13, bubbles: true }));
});

When('I click the destroy button on {string}', function (title) {
  const li = findTodoLi.call(this, title);
  assert.ok(li, `todo "${title}" should exist`);
  const destroyBtn = li.querySelector('.destroy');
  assert.ok(destroyBtn, 'destroy button should exist');
  destroyBtn.click();
});

When('I double-click the label of {string}', function (title) {
  const label = findTodoLabel.call(this, title);
  assert.ok(label, `label for "${title}" should exist`);
  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
});

When('I change the edit input to {string} and press Enter', function (newValue) {
  const editInput = qs.call(this, '.todo-list li.editing .edit');
  assert.ok(editInput, 'edit input should be visible');
  editInput.value = newValue;
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
  editInput.dispatchEvent(new this.window.KeyboardEvent('keypress', { key: 'Enter', keyCode: 13, bubbles: true }));
  editInput.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('I change the edit input to {string} and blur the input', function (newValue) {
  const editInput = qs.call(this, '.todo-list li.editing .edit');
  assert.ok(editInput, 'edit input should be visible');
  editInput.value = newValue;
  editInput.dispatchEvent(new this.window.Event('focusout', { bubbles: true }));
  editInput.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
});

When('I clear the edit input and press Enter', function () {
  const editInput = qs.call(this, '.todo-list li.editing .edit');
  assert.ok(editInput, 'edit input should be visible');
  editInput.value = '';
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

When('I change the edit input to {string} and press Escape', function (newValue) {
  const editInput = qs.call(this, '.todo-list li.editing .edit');
  assert.ok(editInput, 'edit input should be visible');
  editInput.value = newValue;
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, bubbles: true }));
});

When('I view the todo count', function () {
  // The count is always visible in the DOM
});

When('I click the checkbox on {string}', function (title) {
  const li = findTodoLi.call(this, title);
  assert.ok(li, `todo "${title}" should exist`);
  const cb = li.querySelector('.toggle');
  assert.ok(cb, 'checkbox should exist');
  cb.click();
  cb.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('I click the toggle-all checkbox', function () {
  const toggleAll = qs.call(this, '#toggle-all');
  toggleAll.checked = !toggleAll.checked;
  toggleAll.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('I click the clear-completed button', function () {
  const btn = qs.call(this, '.clear-completed');
  btn.click();
});

When('I inspect localStorage', function () {
  // Setup step, no assertion needed
});

When('the app is reloaded', function () {
  // Preserve localStorage across reload (loadApp creates new window with empty localStorage)
  const savedData = this.window.localStorage.getItem('todos-vanilla');
  const savedFilter = this.window.localStorage.getItem('todos-vanilla-filter');
  this.loadApp();
  if (savedData !== null) {
    this.window.localStorage.setItem('todos-vanilla', savedData);
  }
  if (savedFilter !== null) {
    this.window.localStorage.setItem('todos-vanilla-filter', savedFilter);
  }
  if (this.window.__render) this.window.__render();
});

When('the app is reloaded without saving the edit', function () {
  const savedData = this.window.localStorage.getItem('todos-vanilla');
  const savedFilter = this.window.localStorage.getItem('todos-vanilla-filter');
  this.loadApp();
  if (savedData !== null) {
    this.window.localStorage.setItem('todos-vanilla', savedData);
  }
  if (savedFilter !== null) {
    this.window.localStorage.setItem('todos-vanilla-filter', savedFilter);
  }
  if (this.window.__render) this.window.__render();
});

// ---------------------------------------------------------------------------
// Then steps
// ---------------------------------------------------------------------------

Then('{string} appears in the todo list', function (title) {
  const label = findTodoLabel.call(this, title);
  assert.ok(label, `"${title}" should appear in the todo list`);
});

Then('the todo input is cleared', function () {
  const input = qs.call(this, '.new-todo');
  assert.strictEqual(input.value, '', 'todo input should be cleared');
});

Then('#main and #footer are visible', function () {
  assert.ok(isVisible.call(this, qs.call(this, '.main')), '#main should be visible');
  assert.ok(isVisible.call(this, qs.call(this, '.footer')), '#footer should be visible');
});

Then('no new todo is added to the list', function () {
  assert.strictEqual(qsa.call(this, '.todo-list li').length, 0, 'no todo should be added');
});

Then('#main is hidden', function () {
  assert.ok(isHidden.call(this, qs.call(this, '.main')), '#main should be hidden');
});

Then('#footer is hidden', function () {
  assert.ok(isHidden.call(this, qs.call(this, '.footer')), '#footer should be hidden');
});

Then('{string} is removed from the todo list', function (title) {
  assert.strictEqual(findTodoLabel.call(this, title), null, `"${title}" should be removed`);
});

Then('{string} is in the todo list', function (title) {
  assert.ok(findTodoLabel.call(this, title), `"${title}" should be in the todo list`);
});

Then('the todo item has the editing class', function () {
  assert.ok(qs.call(this, '.todo-list li.editing'), 'a todo item should have editing class');
});

Then('the edit input is focused', function () {
  const editInput = qs.call(this, '.todo-list li.editing .edit');
  assert.ok(editInput, 'edit input should exist');
  assert.strictEqual(this.document.activeElement, editInput, 'edit input should be focused');
});

Then('the edit input contains {string}', function (value) {
  const editInput = qs.call(this, '.todo-list li.editing .edit');
  assert.strictEqual(editInput.value, value, `edit input should contain "${value}"`);
});

Then('{string} is not in the todo list', function (title) {
  assert.strictEqual(findTodoLabel.call(this, title), null, `"${title}" should not be in the todo list`);
});

Then('the editing class is removed', function () {
  assert.strictEqual(qsa.call(this, '.todo-list li.editing').length, 0, 'editing class should be removed');
});

Then('the count shows {string}', function (expected) {
  assert.strictEqual(textOf(qs.call(this, '.todo-count strong')), expected, `count should show ${expected}`);
});

Then('the count label says {string}', function (expected) {
  const text = textOf(qs.call(this, '.todo-count'));
  assert.ok(text.includes(expected), `count label should contain "${expected}", got "${text}"`);
});

Then('{string} has the completed class', function (title) {
  const li = findTodoLi.call(this, title);
  assert.ok(li, `todo "${title}" should exist`);
  assert.ok(li.classList.contains('completed'), `"${title}" should have completed class`);
});

Then('{string} does not have the completed class', function (title) {
  const li = findTodoLi.call(this, title);
  assert.ok(li, `todo "${title}" should exist`);
  assert.ok(!li.classList.contains('completed'), `"${title}" should not have completed class`);
});

Then('its checkbox is checked', function () {
  const checkeds = qsa.call(this, '.todo-list li .toggle:checked');
  assert.ok(checkeds.length > 0, 'at least one checkbox should be checked');
});

Then('its checkbox is not checked', function () {
  const uncheckeds = qsa.call(this, '.todo-list li .toggle:not(:checked)');
  const checkeds = qsa.call(this, '.todo-list li .toggle:checked');
  assert.ok(uncheckeds.length > 0 || checkeds.length === 0, 'at least one checkbox should not be checked');
});

Then('all todos have the completed class', function () {
  const items = qsa.call(this, '.todo-list li');
  assert.ok(items.length > 0, 'there should be todos');
  for (const li of items) {
    assert.ok(li.classList.contains('completed'), 'all todos should have completed class');
  }
});

Then('the toggle-all checkbox is checked', function () {
  assert.ok(qs.call(this, '#toggle-all').checked, 'toggle-all checkbox should be checked');
});

Then('the toggle-all checkbox is not checked', function () {
  assert.ok(!qs.call(this, '#toggle-all').checked, 'toggle-all checkbox should not be checked');
});

Then('no todo has the completed class', function () {
  assert.strictEqual(qsa.call(this, '.todo-list li.completed').length, 0, 'no todo should have completed class');
});

Then('the clear-completed button is hidden', function () {
  assert.ok(isHidden.call(this, qs.call(this, '.clear-completed')), 'clear-completed button should be hidden');
});

Then('the clear-completed button is visible', function () {
  assert.ok(isVisible.call(this, qs.call(this, '.clear-completed')), 'clear-completed button should be visible');
});

Then('{string} is saved in localStorage under key {string}', function (title, key) {
  const raw = this.window.localStorage.getItem(key);
  assert.ok(raw, `localStorage key "${key}" should exist`);
  const todos = JSON.parse(raw);
  assert.ok(todos.find(t => t.title === title), `todo "${title}" should be saved in localStorage`);
});

Then('each stored todo has {string}, {string}, and {string} properties', function (prop1, prop2, prop3) {
  const todos = todoData.call(this);
  for (const t of todos) {
    assert.ok(Object.prototype.hasOwnProperty.call(t, prop1), `todo should have "${prop1}" property`);
    assert.ok(Object.prototype.hasOwnProperty.call(t, prop2), `todo should have "${prop2}" property`);
    assert.ok(Object.prototype.hasOwnProperty.call(t, prop3), `todo should have "${prop3}" property`);
  }
});

Then('the stored todo {string} has completed set to true', function (title) {
  const todos = todoData.call(this);
  const found = todos.find(t => t.title === title);
  assert.ok(found, `todo "${title}" should exist in localStorage`);
  assert.strictEqual(found.completed, true, `"${title}" should have completed=true`);
});

Then('the stored todo {string} has title {string}', function (oldTitle, newTitle) {
  const todos = todoData.call(this);
  // Title may have been updated already; search by either old or new title
  const found = todos.find(t => t.title === oldTitle || t.title === newTitle);
  assert.ok(found, `todo "${oldTitle}" should exist in localStorage`);
  assert.strictEqual(found.title, newTitle, `title should be "${newTitle}"`);
});

Then('{string} is removed from localStorage', function (title) {
  const todos = todoData.call(this);
  assert.strictEqual(todos.find(t => t.title === title), undefined,
    `"${title}" should be removed from localStorage`);
});

Then('{string} remains in localStorage', function (title) {
  assert.ok(todoData.call(this).find(t => t.title === title),
    `"${title}" should remain in localStorage`);
});

Then('it has the completed class', function () {
  assert.ok(qsa.call(this, '.todo-list li.completed').length > 0, 'a completed todo should exist');
});

Then('the todo {string} is not in editing mode', function (title) {
  const li = findTodoLi.call(this, title);
  assert.ok(li, `todo "${title}" should exist`);
  assert.ok(!li.classList.contains('editing'), `"${title}" should not be in editing mode`);
});

Then('all {int} todos are visible in the list', function (count) {
  const items = qsa.call(this, '.todo-list li');
  assert.strictEqual(items.length, count, `should show ${count} todos`);
  for (const li of items) {
    assert.ok(isVisible.call(this, li), 'each todo should be visible');
  }
});

Then('the {string} filter link has the selected class', function (linkText) {
  const links = qsa.call(this, '.filters a');
  let found = false;
  for (const a of links) {
    if (textOf(a) === linkText && a.classList.contains('selected')) { found = true; break; }
  }
  assert.ok(found, `"${linkText}" filter link should have selected class`);
});

Then('only active todos are visible', function () {
  const items = qsa.call(this, '.todo-list li');
  for (const li of items) {
    if (li.classList.contains('completed')) {
      assert.ok(isHidden.call(this, li), 'completed todos should be hidden in active filter');
    } else {
      assert.ok(isVisible.call(this, li), 'active todos should be visible');
    }
  }
});

Then('completed todos are hidden', function () {
  const items = qsa.call(this, '.todo-list li.completed');
  for (const li of items) {
    assert.ok(isHidden.call(this, li), 'completed todos should be hidden');
  }
});

Then('only completed todos are visible', function () {
  const items = qsa.call(this, '.todo-list li');
  for (const li of items) {
    if (li.classList.contains('completed')) {
      assert.ok(isVisible.call(this, li), 'completed todos should be visible');
    } else {
      assert.ok(isHidden.call(this, li), 'active todos should be hidden in completed filter');
    }
  }
});

Then('active todos are hidden', function () {
  const items = qsa.call(this, '.todo-list li:not(.completed)');
  for (const li of items) {
    assert.ok(isHidden.call(this, li), 'active todos should be hidden in completed filter');
  }
});

Then('{string} is hidden from the list', function (title) {
  const li = findTodoLi.call(this, title);
  // In filtered views, items may be removed from the DOM entirely
  if (li) {
    assert.ok(isHidden.call(this, li), `"${title}" should be hidden`);
  }
  // If li is null, the item is removed from the DOM (definitively hidden)
});

const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  loadApp() {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // The app must EXECUTE, not merely be present. Two things were measured 2026-07-28 and both
    // bit an earlier version of this harness:
    //   1. happy-dom does NOT run scripts the parser sees — neither an appended <script> with
    //      textContent nor one inlined into document.write(). window.eval() DOES run them. An
    //      earlier harness looked green while app.js never ran, because its only assertion
    //      checked that the PAGE had loaded. A weak test hid a broken loader.
    //   2. DOMContentLoaded never fires from write()/close(), so an app that defers its init to
    //      DOMContentLoaded or window.load — the common TodoMVC shape — would never initialise
    //      and the harness would fail CORRECT code. The lifecycle events are dispatched here.
    // disableJavaScriptFileLoading stops the page's own src tag attempting a network fetch
    // (ECONNREFUSED under happy-dom, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }
}

setWorldConstructor(AppWorld);

// Every scenario gets the real app. No scenario can pass without one.
Before(function () { this.loadApp(); });
// ...and every scenario gives it back.
After(async function () { await this.disposeApp(); });

/**
 * TodoMVC - Vanilla JS implementation
 */

(function () {
  'use strict';

  var STORAGE_KEY = 'todos-vanilla';
  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;

  // -----------------------------------------------------------------------
  // Model
  // -----------------------------------------------------------------------

  /** @planks("Load persisted todos on page load") */
  /** @planks("Load completed state from localStorage") */
  function loadTodos() {
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
    } catch (e) {
      return [];
    }
  }

  /** @planks("{string} is saved in localStorage under key {string}") */
  /** @planks("each stored todo has {string}, {string}, and {string} properties") */
  function saveTodos(todos) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function nextId() {
    return Date.now() + Math.random();
  }

  // -----------------------------------------------------------------------
  // View helpers
  // -----------------------------------------------------------------------

  var todoApp = document.querySelector('.todoapp');
  var mainEl = todoApp.querySelector('.main');
  var footerEl = todoApp.querySelector('.footer');
  var todoListEl = todoApp.querySelector('.todo-list');
  var newTodoInput = todoApp.querySelector('.new-todo');
  var toggleAllCheckbox = todoApp.querySelector('#toggle-all');
  var todoCountStrong = todoApp.querySelector('.todo-count strong');
  var todoCountEl = todoApp.querySelector('.todo-count');
  var clearCompletedBtn = todoApp.querySelector('.clear-completed');
  var filterLinks = todoApp.querySelectorAll('.filters a');

  // -----------------------------------------------------------------------
  // Router state
  // -----------------------------------------------------------------------

  var currentFilter = 'all';
  var FILTER_KEY = 'todos-vanilla-filter';

  function getFilterFromHash() {
    var hash = window.location.hash || '#/';
    if (hash === '#/active') return 'active';
    if (hash === '#/completed') return 'completed';
    return 'all';
  }

  function saveFilter(filter) {
    try { localStorage.setItem(FILTER_KEY, filter); } catch (e) { /* ignore */ }
  }

  function loadFilter() {
    try {
      var f = localStorage.getItem(FILTER_KEY);
      if (f === 'active' || f === 'completed') return f;
    } catch (e) { /* ignore */ }
    return 'all';
  }

  function setFilterLinkSelected(filter) {
    for (var i = 0; i < filterLinks.length; i++) {
      var a = filterLinks[i];
      a.classList.toggle('selected', a.getAttribute('href') === '#/' + (filter === 'all' ? '' : filter));
    }
  }

  // -----------------------------------------------------------------------
  // Render
  // -----------------------------------------------------------------------

  function filterTodos(todos, filter) {
    if (filter === 'active') return todos.filter(function (t) { return !t.completed; });
    if (filter === 'completed') return todos.filter(function (t) { return t.completed; });
    return todos;
  }

  /** @planks("#main and #footer are visible") */
  /** @planks("#main is hidden") */
  /** @planks("#footer is hidden") */
  /** @planks("the todo item has the editing class") */
  /** @planks("the editing class is removed") */
  /** @planks("the count shows {string}") */
  /** @planks("the count label says {string}") */
  /** @planks("the toggle-all checkbox is checked") */
  /** @planks("the toggle-all checkbox is not checked") */
  /** @planks("the clear-completed button is hidden") */
  /** @planks("the clear-completed button is visible") */
  function render() {
    var todos = loadTodos();
    var filter = currentFilter;
    var filtered = filterTodos(todos, filter);
    var activeCount = todos.filter(function (t) { return !t.completed; }).length;

    // Show/hide main and footer
    var hasTodos = todos.length > 0;
    mainEl.style.display = hasTodos ? 'block' : 'none';
    footerEl.style.display = hasTodos ? 'block' : 'none';

    // Clear and rebuild list
    todoListEl.innerHTML = '';
    for (var i = 0; i < filtered.length; i++) {
      var t = filtered[i];
      var li = document.createElement('li');
      if (t.completed) li.classList.add('completed');

      li.innerHTML =
        '<div class="view">' +
          '<input class="toggle" type="checkbox"' + (t.completed ? ' checked' : '') + '>' +
          '<label>' + escapeHtml(t.title) + '</label>' +
          '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + escapeHtml(t.title) + '">';

      todoListEl.appendChild(li);
    }

    // Update count
    todoCountStrong.textContent = String(activeCount);
    todoCountEl.childNodes[1].textContent = activeCount === 1 ? ' item left' : ' items left';

    // Toggle-all state
    toggleAllCheckbox.checked = todos.length > 0 && activeCount === 0;

    // Clear completed visibility
    var completedCount = todos.length - activeCount;
    clearCompletedBtn.style.display = completedCount > 0 ? 'block' : 'none';

    // Filter link selected state
    setFilterLinkSelected(filter);
  }

  function escapeHtml(str) {
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(str));
    return div.innerHTML;
  }

  // -----------------------------------------------------------------------
  // Actions
  // -----------------------------------------------------------------------

  /** @planks("I type {string} into the todo input and press Enter") */
  function addTodo(title) {
    title = title.trim();
    if (title === '') return;
    var todos = loadTodos();
    todos.push({ id: nextId(), title: title, completed: false });
    saveTodos(todos);
    render();
  }

  /** @planks("I click the destroy button on {string}") */
  function deleteTodo(title) {
    var todos = loadTodos();
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].title === title) {
        todos.splice(i, 1);
        break;
      }
    }
    saveTodos(todos);
    render();
  }

  /** @planks("I click the checkbox on {string}") */
  function toggleTodo(title) {
    var todos = loadTodos();
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].title === title) {
        todos[i].completed = !todos[i].completed;
        break;
      }
    }
    saveTodos(todos);
    render();
  }

  /** @planks("I click the toggle-all checkbox") */
  function toggleAll(completed) {
    var todos = loadTodos();
    for (var i = 0; i < todos.length; i++) {
      todos[i].completed = completed;
    }
    saveTodos(todos);
    render();
  }

  /** @planks("I click the clear-completed button") */
  function clearCompleted() {
    var todos = loadTodos();
    todos = todos.filter(function (t) { return !t.completed; });
    saveTodos(todos);
    render();
  }

  /** @planks("I change the edit input to {string} and press Enter") */
  /** @planks("I change the edit input to {string} and blur the input") */
  /** @planks("I clear the edit input and press Enter") */
  /** @planks("I change the edit input to {string} and press Escape") */
  function updateTodo(oldTitle, newTitle) {
    newTitle = newTitle.trim();
    var todos = loadTodos();
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].title === oldTitle) {
        if (newTitle === '') {
          todos.splice(i, 1);
        } else {
          todos[i].title = newTitle;
        }
        break;
      }
    }
    saveTodos(todos);
    render();
  }

  function findByTitle(title) {
    var todos = loadTodos();
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].title === title) return todos[i];
    }
    return null;
  }

  // -----------------------------------------------------------------------
  // Event handlers
  // -----------------------------------------------------------------------

  newTodoInput.addEventListener('keydown', function (e) {
    if (e.keyCode === ENTER_KEY) {
      addTodo(newTodoInput.value);
      newTodoInput.value = '';
    }
  });

  newTodoInput.addEventListener('change', function () {
    // change event for step definitions that trigger it
  });

  todoListEl.addEventListener('change', function (e) {
    var target = e.target;
    if (target.classList.contains('toggle')) {
      var li = target.closest('li');
      var label = li ? li.querySelector('label') : null;
      if (label) {
        toggleTodo(label.textContent.trim());
      }
    }
  });

  todoListEl.addEventListener('click', function (e) {
    var target = e.target;
    if (target.classList.contains('destroy')) {
      var li = target.closest('li');
      var label = li ? li.querySelector('label') : null;
      if (label) {
        deleteTodo(label.textContent.trim());
      }
    }
  });

  todoListEl.addEventListener('dblclick', function (e) {
    var target = e.target;
    if (target.tagName === 'LABEL') {
      var li = target.closest('li');
      if (li) {
        li.classList.add('editing');
        var editInput = li.querySelector('.edit');
        editInput.value = target.textContent.trim();
        editInput.focus();
      }
    }
  });

  todoListEl.addEventListener('focusout', function (e) {
    var target = e.target;
    if (target.classList.contains('edit')) {
      var li = target.closest('li');
      if (li && li.classList.contains('editing')) {
        var oldTitle = li.querySelector('label').textContent.trim();
        var newTitle = target.value.trim();
        if (newTitle === '') {
          deleteTodo(oldTitle);
        } else if (newTitle !== oldTitle) {
          updateTodo(oldTitle, newTitle);
        }
        li.classList.remove('editing');
      }
    }
  });

  todoListEl.addEventListener('blur', function (e) {
    var target = e.target;
    if (target.classList.contains('edit')) {
      var li = target.closest('li');
      if (li && li.classList.contains('editing')) {
        var oldTitle = li.querySelector('label').textContent.trim();
        var newTitle = target.value.trim();
        if (newTitle === '') {
          deleteTodo(oldTitle);
        } else if (newTitle !== oldTitle) {
          updateTodo(oldTitle, newTitle);
        }
        li.classList.remove('editing');
      }
    }
  }, true);

  todoListEl.addEventListener('keydown', function (e) {
    var target = e.target;
    if (target.classList.contains('edit')) {
      var li = target.closest('li');
      if (!li) return;
      var oldTitle = li.querySelector('label').textContent.trim();

      if (e.keyCode === ENTER_KEY) {
        var newTitle = target.value.trim();
        if (newTitle === '') {
          deleteTodo(oldTitle);
        } else if (newTitle !== oldTitle) {
          updateTodo(oldTitle, newTitle);
        }
        li.classList.remove('editing');
      } else if (e.keyCode === ESCAPE_KEY) {
        target.value = oldTitle;
        li.classList.remove('editing');
      }
    }
  });

  toggleAllCheckbox.addEventListener('change', function () {
    toggleAll(toggleAllCheckbox.checked);
  });

  clearCompletedBtn.addEventListener('click', function () {
    clearCompleted();
  });

  // -----------------------------------------------------------------------
  // Routing
  // -----------------------------------------------------------------------

  window.addEventListener('hashchange', function () {
    currentFilter = getFilterFromHash();
    saveFilter(currentFilter);
    render();
  });

  // -----------------------------------------------------------------------
  // Init
  // -----------------------------------------------------------------------

  currentFilter = loadFilter();
  // Sync hash to restored filter
  var desiredHash = currentFilter === 'all' ? '#/' : '#/' + currentFilter;
  if (window.location.hash !== desiredHash) {
    window.location.hash = desiredHash;
  }
  render();

  // Expose render for test support
  window.__render = render;
})();

